import {clone,uid} from './model.js';
import {captureProduct,assertProductSource} from './product-workflow.js';
import {validateLandscapeRecipe} from './landscape-recipe.js';
export function captureLandscape(doc,layer){if(doc.selection)throw Error('Bỏ vùng chọn tài liệu trước khi mở Phong cảnh HDR.');if(layer?.landscapeRecipe&&layer.locked)throw Error('Mở khóa layer trước khi sửa phong cảnh.');return captureProduct(doc,layer);}
export function applyLandscape(doc,snapshot,output,recipe,assets){const current=assertProductSource(doc,snapshot),reopen=!!current.landscapeRecipe;if(current.smartObjectId||current.clipToBelow||reopen&&current.locked)throw Error('Layer không cho phép chỉnh phong cảnh.');if(!reopen&&doc.layers.length>=150)throw Error('Đã đạt giới hạn 150 layer.');validateLandscapeRecipe(recipe,s=>{if(typeof s!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(s)&&s!=='assets/wave.jpg')throw Error('Invalid landscape source.');});if(output?.width!==recipe.width||output?.height!==recipe.height)throw Error('Landscape output does not match source.');const source=output.toDataURL(),next={...clone(current),source,landscapeRecipe:clone(recipe)};for(const k of ['photoRecipe','removalRecipe','productRecipe','cutoutRecipe','paperRecipe','colorRecipe','sceneRecipe','artRecipe','generation','assistance'])delete next[k];if(!reopen){next.id=uid();next.visible=true;next.locked=false;next.name=current.name.slice(0,130)+' · Phong cảnh HDR';}assets.set(source,output);if(reopen)Object.assign(current,next);else{doc.layers.splice(doc.layers.indexOf(current)+1,0,next);current.visible=false;}doc.activeId=next.id;doc.selectedIds=[next.id];return next;}
